import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService, RegisterRequest } from '../../../core/services/auth.service';
import { I18nService } from '../../../core/i18n/i18n.service';
import { TranslationPipe } from '../../../core/i18n/translation.pipe';
import { LangSwitchComponent } from '../../../core/i18n/lang-switch.component';

@Component({
  selector: 'app-register',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, TranslationPipe, LangSwitchComponent],
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.scss']
})
export class RegisterComponent {
  form: FormGroup;
  isLoading = false;
  hasError = false;
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router,
    private i18nService: I18nService
  ) {
    this.form = this.fb.group({
      nome: ['', [Validators.required, Validators.minLength(3)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required]]
    }, {
      validators: this.passwordMatchValidator
    });
  }

  get nome() {
    return this.form.get('nome');
  }

  get email() {
    return this.form.get('email');
  }

  get password() {
    return this.form.get('password');
  }

  get confirmPassword() {
    return this.form.get('confirmPassword');
  }

  passwordMatchValidator(form: FormGroup): { [key: string]: boolean } | null {
    const password = form.get('password');
    const confirmPassword = form.get('confirmPassword');

    if (!password || !confirmPassword) {
      return null;
    }

    return password.value === confirmPassword.value ? null : { passwordMismatch: true };
  }

  register(): void {
    if (this.form.invalid) {
      return;
    }

    this.isLoading = true;
    this.hasError = false;

    const data: RegisterRequest = {
      nome: this.form.value.nome,
      email: this.form.value.email,
      senha: this.form.value.password as string
    };

    this.authService.register(data).subscribe({
      next: () => {
        this.isLoading = false;
        this.router.navigate(['/dashboard']);
      },
      error: (error: any) => {
        this.isLoading = false;
        this.hasError = true;
        this.errorMessage = error?.error?.message || this.i18nService.translate('register.registerError');
      }
    });
  }

  goToLogin(): void {
    this.router.navigate(['/login']);
  }
}
<div class="register-container">
  <div class="register-card">
    <app-lang-switch></app-lang-switch>
    <h1>{{ 'common.appName' | t }}</h1>
    <p class="subtitle">{{ 'register.subtitle' | t }}</p>

    <form [formGroup]="form" (ngSubmit)="register()" class="register-form">
      <div class="form-group">
        <label for="nome">{{ 'register.fullNameLabel' | t }}</label>
        <input
          id="nome"
          type="text"
          formControlName="nome"
          class="form-input"
          [placeholder]="'register.fullNamePlaceholder' | t"
          [class.error]="nome?.invalid && nome?.touched"
        />
        <span class="error-message" *ngIf="nome?.invalid && nome?.touched">
          <span *ngIf="nome?.errors?.['required']">{{ 'register.fullNameRequired' | t }}</span>
          <span *ngIf="nome?.errors?.['minlength']">{{ 'register.fullNameMinLength' | t }}</span>
        </span>
      </div>

      <div class="form-group">
        <label for="email">{{ 'login.emailLabel' | t }}</label>
        <input
          id="email"
          type="email"
          formControlName="email"
          class="form-input"
          [placeholder]="'login.emailPlaceholder' | t"
          [class.error]="email?.invalid && email?.touched"
        />
        <span class="error-message" *ngIf="email?.invalid && email?.touched">
          <span *ngIf="email?.errors?.['required']">{{ 'login.emailRequired' | t }}</span>
          <span *ngIf="email?.errors?.['email']">{{ 'login.emailInvalid' | t }}</span>
        </span>
      </div>

      <div class="form-group">
        <label for="password">{{ 'login.passwordLabel' | t }}</label>
        <input
          id="password"
          type="password"
          formControlName="password"
          class="form-input"
          [placeholder]="'login.passwordPlaceholder' | t"
          [class.error]="password?.invalid && password?.touched"
        />
        <span class="error-message" *ngIf="password?.invalid && password?.touched">
          <span *ngIf="password?.errors?.['required']">{{ 'login.passwordRequired' | t }}</span>
          <span *ngIf="password?.errors?.['minlength']">{{ 'login.passwordMinLength' | t }}</span>
        </span>
      </div>

      <div class="form-group">
        <label for="confirmPassword">{{ 'register.confirmPasswordLabel' | t }}</label>
        <input
          id="confirmPassword"
          type="password"
          formControlName="confirmPassword"
          class="form-input"
          [placeholder]="'login.passwordPlaceholder' | t"
          [class.error]="confirmPassword?.invalid && confirmPassword?.touched"
        />
        <span class="error-message" *ngIf="confirmPassword?.invalid && confirmPassword?.touched">
          <span *ngIf="confirmPassword?.errors?.['required']">{{ 'register.confirmPasswordRequired' | t }}</span>
        </span>
        <span class="error-message" *ngIf="form.errors?.['passwordMismatch'] && confirmPassword?.touched">
          {{ 'register.passwordMismatch' | t }}
        </span>
      </div>

      <div class="alert alert-error" *ngIf="hasError">
        {{ errorMessage }}
      </div>

      <button
        type="submit"
        class="btn btn-primary"
        [disabled]="form.invalid || isLoading"
      >
        <span *ngIf="!isLoading">{{ 'register.submit' | t }}</span>
        <span *ngIf="isLoading">{{ 'register.submitting' | t }}</span>
      </button>
    </form>

    <div class="form-footer">
      <p>{{ 'register.hasAccount' | t }} <a href="javascript:void(0)" (click)="goToLogin()">{{ 'register.loginHere' | t }}</a></p>
    </div>
  </div>
</div>
